// 파서가 생성하는 AST 구조 정의

// ============================================================================
// Program Structure
// ============================================================================

type Program = {
  definitions: Vec(Definition),
  statements: Vec(Statement),
}

type Definition =
  | Function {
      name: String,
      params: Vec(String),
      body: Vec(Statement),
    }
  | TypeDef {
      name: String,
    }

// ============================================================================
// Statements
// ============================================================================

type Statement =
  | LetBinding {
      name: String,
      value: Expression,
    }
  | Return(Expression)
  | If {
      condition: Expression,
      then_branch: Vec(Statement),
      else_branch: Option(Vec(Statement)),
    }
  | Expression(Expression)

// ============================================================================
// Expressions
// ============================================================================

type Expression =
  | Literal(Literal)
  | Variable(String)
  | BinaryOp {
      op: String,
      left: Expression,
      right: Expression,
    }
  | UnaryOp {
      op: String,
      operand: Expression,
    }
  | FunctionCall {
      name: String,
      args: Vec(Expression),
    }
  | IfExpr {
      condition: Expression,
      then_expr: Expression,
      else_expr: Option(Expression),
    }
  | Match {
      expr: Expression,
      patterns: Vec((String, Expression)),
    }
  | Array {
      elements: Vec(Expression),
    }
  | Index {
      expr: Expression,
      index: Expression,
    }
  | Tuple {
      elements: Vec(Expression),
    }

// ============================================================================
// Literals
// ============================================================================

type Literal =
  | Integer(i64)
  | Float(f64)
  | String(String)
  | Boolean(bool)

// ============================================================================
// Type System
// ============================================================================

type Type =
  | I64
  | F64
  | Str
  | Bool
  | Array(Type)
  | Tuple(Vec(Type))
  | Custom(String)
  | Unknown

// ============================================================================
// Helper Functions
// ============================================================================

// Program 생성
fn create_program(defs: Vec(Definition), stmts: Vec(Statement)) -> Program {
  Program {
    definitions: defs,
    statements: stmts,
  }
}

// Function Definition 생성
fn create_function(name: String, params: Vec(String), body: Vec(Statement)) -> Definition {
  Function {
    name: name,
    params: params,
    body: body,
  }
}

// Let Binding 생성
fn create_let_binding(name: String, value: Expression) -> Statement {
  LetBinding {
    name: name,
    value: value,
  }
}

// Variable Expression 생성
fn create_variable(name: String) -> Expression {
  Variable(name)
}

// Integer Literal 생성
fn create_integer(value: i64) -> Expression {
  Literal(Integer(value))
}

// Float Literal 생성
fn create_float(value: f64) -> Expression {
  Literal(Float(value))
}

// String Literal 생성
fn create_string(value: String) -> Expression {
  Literal(String(value))
}

// Boolean Literal 생성
fn create_boolean(value: bool) -> Expression {
  Literal(Boolean(value))
}

// Binary Operation 생성
fn create_binary_op(op: String, left: Expression, right: Expression) -> Expression {
  BinaryOp {
    op: op,
    left: left,
    right: right,
  }
}

// Function Call 생성
fn create_function_call(name: String, args: Vec(Expression)) -> Expression {
  FunctionCall {
    name: name,
    args: args,
  }
}

// If Expression 생성
fn create_if_expr(
  cond: Expression,
  then_e: Expression,
  else_e: Option(Expression)
) -> Expression {
  IfExpr {
    condition: cond,
    then_expr: then_e,
    else_expr: else_e,
  }
}

// Array Expression 생성
fn create_array(elements: Vec(Expression)) -> Expression {
  Array {
    elements: elements,
  }
}

