// FV 2.0 Lexer: V-호환 문법 지원
// V 언어의 토큰을 정의하고, 소스 코드를 토큰 스트림으로 변환

use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Token {
    // 키워드
    Fn,
    Let,
    Mut,
    Const,
    If,
    Else,
    For,
    In,
    Match,
    Type,
    Struct,
    Interface,
    Enum,
    Trait,
    Impl,
    Return,
    Module,
    Import,

    // 리터럴
    Identifier(String),
    Integer(i64),
    Float(f64),
    String(String),
    RawString(String),
    True,
    False,
    None,

    // 연산자
