func (c *Checker) checkStatement(stmt ast.Statement) Type {
	switch s := stmt.(type) {
	case *ast.LetStatement:
		return c.checkLetStatement(s)
	case *ast.ConstStatement:
		return c.checkConstStatement(s)
	case *ast.IfStatement:
		return c.checkIfStatement(s)
	case *ast.ForStatement:
		return c.checkForStatement(s)
	case *ast.ForRangeStatement:
		return c.checkForRangeStatement(s)
	case *ast.ReturnStatement:
		return c.checkReturnStatement(s)
	case *ast.MatchStatement:
		return c.checkMatchStatement(s)
	case *ast.ExpressionStatement:
		return c.checkExpression(s.Expression)
	case *ast.BlockStatement:
		return c.checkBlockStatement(s)
	}
	return &PrimitiveType{Name: "none"}
}

func (c *Checker) checkLetStatement(let *ast.LetStatement) Type {
	initType := c.checkExpression(let.Init)

	var declaredType Type
	if let.Type != nil {
		declaredType = c.astTypeToCheckerType(let.Type)

		// Verify init matches declared type
		if !initType.Equal(declaredType) {
			c.addError(0, 0, fmt.Sprintf(
				"let %s: expected type %s, got %s",
				let.Name, declaredType.TypeString(), initType.TypeString(),
			))
		}
	} else {
		declaredType = initType
	}

	c.CurrentScope.Define(let.Name, declaredType, "var")
	return declaredType
}

func (c *Checker) checkConstStatement(const_ *ast.ConstStatement) Type {
	initType := c.checkExpression(const_.Value)

	var declaredType Type
	if const_.Type != nil {
		declaredType = c.astTypeToCheckerType(const_.Type)

		if !initType.Equal(declaredType) {
			c.addError(0, 0, fmt.Sprintf(
				"const %s: expected type %s, got %s",
